:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-fog-surface: #f5f5f5;
  --color-cream-tag: #fbf3e0;
  --color-spruce-fill: #0b363b;
  --color-spruce-scrim: #0b363bcc;
  --color-lagoon-ink: #00262b;
  --color-slate-caption: #4d6164;
  --color-pewter-meta: #7a898b;
  --color-mist-border: #e5e8e8;
  --color-sprout-halo: #b6f2a3;
  --color-ochre-marker: #a87a12;
  --color-moss-check: #3f9a4a;

  /* Typography — Font Families */
  --font-saans: "Saans", "Geist", "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 10px;
  --leading-small: 1.375;
  --tracking-small: 0.2px;
  --text-caption: 12px;
  --leading-caption: 1.375;
  --tracking-caption: 0.2px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.375;
  --tracking-body-sm: 0.2px;
  --text-body: 16px;
  --leading-body: 1.375;
  --tracking-body: 0.2px;
  --text-body-lg: 20px;
  --leading-body-lg: 1.375;
  --tracking-body-lg: 0.2px;
  --text-subheading: 20px;
  --leading-subheading: 1.125;
  --tracking-subheading: 0.2px;
  --text-heading-sm: 24px;
  --leading-heading-sm: 1.125;
  --tracking-heading-sm: 0.2px;
  --text-heading: 40px;
  --leading-heading: 1.125;
  --tracking-heading: 0.2px;
  --text-heading-lg: 64px;
  --leading-heading-lg: 1;
  --tracking-heading-lg: 0.2px;
  --text-display: 96px;
  --leading-display: 1;
  --tracking-display: 0.2px;

  /* Typography — Weights */
  --font-weight-regular: 475;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-96: 96px;
  --spacing-128: 128px;
  --spacing-160: 160px;

  /* Layout */
  --layout-page-max-width: 1320px;
  --layout-section-gap: 128px;
  --layout-card-padding: 24px;
  --layout-element-gap: 24px;

  /* Border Radius */
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 6px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-buttons: 9999px;
  --radius-pills: 9999px;
  --radius-tags: 2px;
  --radius-badges: 2px;
  --radius-smallElements: 2px;
  --radius-innerTiles: 4px;
  --radius-images: 6px;
  --radius-cards: 0px;
  --radius-nav: 0px;
  --radius-sections: 0px;

  /* Shadows */
  --shadow-sm: 0px 0px 0px 4px #b6f2a3;
  --shadow-sm-2: 0px 0px 0px 4px #f5f5f5;

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-fog-surface: #f5f5f5;
  --surface-spruce-scrim: #0b363bcc;
  --surface-spruce-fill: #0b363b;
}

